133|fn valid_stub_receipt_json(value: &str, session_id: &str, plan: &str, operation_id: &str) -> bool {
134|    if value.len() > 4096 {
135|        return false;
136|    }
137|    let Ok(receipt) = serde_json::from_str::<serde_json::Value>(value) else {
138|        return false;
139|    };
140|    let Some(object) = receipt.as_object() else {
141|        return false;
142|    };
143|    if receipt["session_id"] != session_id
144|        || receipt["plan_sha256"] != plan
145|        || receipt["operation_id"] != operation_id
146|    {
147|        return false;
148|    }
149|    match receipt["status"].as_str() {
150|        Some("already_absent") => object.len() == 4,
151|        Some("quarantined") => {
152|            object.len() == 9
153|                && receipt["path"].as_str().is_some_and(|path| {
154|                    Path::new(path).is_absolute()
155|                        && Path::new(path)
156|                            .components()
157|                            .all(|part| matches!(part, Component::RootDir | Component::Normal(_)))
158|                })
159|                && receipt["original_stub_inode"]
160|                    .as_u64()
161|                    .is_some_and(|id| id > 0)
162|                && receipt["backup_inode"].as_u64().is_some_and(|id| id > 0)
163|                && receipt["backup_sha256"]
164|                    .as_str()
165|                    .is_some_and(valid_root_repair_digest)
166|                && receipt["original_stub_mode"].as_u64() == Some(0o100)
167|        }
168|        _ => false,
169|    }
170|}
