231|fn open_directory(path: &Path, create: bool) -> std::result::Result<File, CozoError> {
232|    let path = if path.is_absolute() {
233|        path.to_path_buf()
234|    } else {
235|        std::env::current_dir().map_err(native)?.join(path)
236|    };
237|    if path == Path::new("/") {
238|        return Err(err("database directory cannot be filesystem root"));
239|    }
240|    let mut current = File::open("/").map_err(native)?;
241|    for part in path.components() {
242|        let Component::Normal(name) = part else {
243|            if matches!(part, Component::RootDir) {
244|                continue;
245|            }
246|            return Err(err("database directory cannot contain dot components"));
247|        };
248|        let open = |directory: &File| {
249|            nix::fcntl::openat(
250|                Some(directory.as_raw_fd()),
251|                name,
252|                OFlag::O_RDONLY | OFlag::O_DIRECTORY | OFlag::O_NOFOLLOW | OFlag::O_CLOEXEC,
253|                Mode::empty(),
254|            )
255|        };
256|        let raw = match open(&current) {
257|            Ok(raw) => raw,
258|            Err(nix::errno::Errno::ENOENT) if create => {
259|                match nix::sys::stat::mkdirat(
260|                    Some(current.as_raw_fd()),
261|                    name,
262|                    Mode::from_bits_truncate(0o700),
263|                ) {
264|                    Ok(()) | Err(nix::errno::Errno::EEXIST) => {}
265|                    Err(error) => return Err(native(error)),
266|                }
267|                open(&current).map_err(native)?
268|            }
269|            Err(error) => return Err(native(error)),
270|        };
271|        // SAFETY: nix0.28 returns a newly owned fd, transferred once to File.
272|        current = unsafe { File::from_raw_fd(raw) };
273|    }
274|    let metadata = current.metadata().map_err(native)?;
275|    if metadata.uid() != nix::unistd::geteuid().as_raw() || metadata.mode() & 0o022 != 0 {
276|        return Err(err(
277|            "persistent database directory must be owned by service and not group/world writable",
278|        ));
279|    }
280|    Ok(current)
281|}
