1|//! Native Incus lifecycle observation and complete-root publication.
2|//!
3|//! The WebSocket is only a wakeup source. Every accepted lifecycle event is
4|//! followed by a strict full default-project readback; event payloads never
5|//! become plugin state.
6|
7|use crate::{
8|    method_contract_admission::admit_compiled_state_contract,
9|    mutation_engine::MutationEngine,
10|    sealed_schema_reader::{blob_catalog_dir_from_env, read_manifest_pinned_schema_document},
11|};
12|use anyhow::{Context, Result, ensure};
13|use op_plugins::state_plugins::incus::{
14|    IncusLifecycleObserver, IncusState, dispatch_incus_method_observed,
15|    subscribe_incus_default_project,
16|};
17|use std::{path::Path, sync::Arc};
18|
19|const PLUGIN: &str = "incus";
20|
21|pub(crate) struct PreparedIncusObservation {
22|    pub full_state: simd_json::OwnedValue,
23|    pub expected_schema_hash: String,
24|}
25|
26|
27|/// Host-side, read-only, metadata-only enrichment of disk device sources.
28|/// Bounded: existing absolute paths only; mode/size are not recorded, only
29|/// the identity token. Fails only on malformed paths, never on missing files.
30|fn attach_mount_identities(state: &mut op_plugins::state_plugins::incus::IncusState) -> Result<()> {
31|    use op_plugins::state_plugins::incus_device::{Device, NamedDevice};
32|    for instance in &mut state.instances {
33|        for field in [&mut instance.devices, &mut instance.expanded_devices] {
34|            for NamedDevice { device, .. } in field.iter_mut() {
35|                let Device::Disk(disk) = device else { continue };
36|                let Some(source) = disk.source.as_deref() else { continue };
37|                disk.source_identity = Some(mount_identity_token(source));
38|            }
39|        }
40|    }
41|    Ok(())
42|}
43|
44|/// `sha256("dev:ino")` truncated to 16 hex chars, or `"-"` when the source is
45|/// unstatable. Never returns raw numbers.
46|fn mount_identity_token(source: &str) -> String {
47|    use sha2::{Digest, Sha256};
48|    use std::os::unix::fs::MetadataExt;
49|    let metadata = || -> Option<std::fs::Metadata> {
50|        if source.len() > 4096
51|            || !source.starts_with('/')
52|            || source.chars().any(|c| c.is_control())
53|        {
54|            return None;
55|        }
56|        std::fs::metadata(source).ok()
57|    }();
58|    match metadata {
59|        Some(metadata) => {
60|            let token = format!("{}:{}", metadata.dev(), metadata.ino());
61|            let digest = Sha256::digest(token.as_bytes());
62|            format!("{digest:x}")[..16].to_string()
63|        }
64|        None => "-".to_string(),
65|    }
66|}
