73|fn prepare_observation(catalog: &Path, snapshot: &IncusState) -> Result<PreparedIncusObservation> {
74|    let pinned = read_manifest_pinned_schema_document(catalog, PLUGIN)?;
75|    admit_compiled_state_contract(&pinned, PLUGIN)?;
76|    let full_state = simd_json::serde::to_owned_value(snapshot)?;
77|    ensure!(
78|        pinned.schema.validate(&full_state).valid,
79|        "native Incus snapshot does not conform to the pinned plugin state schema"
80|    );
81|    pinned.schema.validate_public_state_policy()?;
82|    // Fail closed on an invalid policy or state/type drift. MutationEngine
83|    // repeats this exact pinned projection as the sole authority for audit and
84|    // live notification data while retaining the full private root in SHM.
85|    pinned.schema.project_public_state(&full_state)?;
86|    let after = read_manifest_pinned_schema_document(catalog, PLUGIN)?;
87|    ensure!(
88|        after.schema_hash == pinned.schema_hash
89|            && after.blob.schema_json == pinned.blob.schema_json,
90|        "Incus plugin seal changed during observation validation"
91|    );
92|    Ok(PreparedIncusObservation {
93|        full_state,
94|        expected_schema_hash: pinned.schema_hash,
95|    })
96|}
