98|async fn readback_and_publish(
99|    engine: &MutationEngine,
100|    observer: &IncusLifecycleObserver,
101|) -> Result<()> {
102|    // The same engine lock is held by the canonical Incus method dispatcher
103|    // from native effect through readback and commit. It prevents an older
104|    // observer read from overwriting a newer method observation.
105|    let _observation = engine.lock_host_observation().await;
106|    let mut snapshot = observer.default_project_state().await?;
107|    attach_mount_identities(&mut snapshot)?;
108|    let prepared = prepare_observation(&blob_catalog_dir_from_env(), &snapshot)?;
109|    engine
110|        .process_observed_state(PLUGIN, prepared.full_state, prepared.expected_schema_hash)
111|        .await
112|        .map_err(anyhow::Error::msg)?;
113|    Ok(())
114|}
115|
116|/// Called by identity root repair while it holds `lock_host_observation`
117|/// across the exact native effect and complete default-project readback.
118|/// Keep the same pinned seal and SHM publication path as ordinary Incus calls.
119|pub(crate) async fn publish_repair_readback_locked(
120|    engine: &MutationEngine,
121|    snapshot: &IncusState,
122|) -> Result<()> {
123|    let mut snapshot = snapshot.clone();
124|    attach_mount_identities(&mut snapshot)?;
125|    let prepared = prepare_observation(&blob_catalog_dir_from_env(), &snapshot)?;
126|    engine
127|        .process_observed_state(PLUGIN, prepared.full_state, prepared.expected_schema_hash)
128|        .await
129|        .map_err(anyhow::Error::msg)
130|        .map(|_| ())
131|}
132|
133|/// Subscribe first, then publish one initial complete snapshot. Each native
134|/// lifecycle wakeup produces another complete root replacement. Disconnect or
135|/// malformed data ends this task without deleting the last committed state;
136|/// only an explicit engine start/reload retries it.
137|pub(crate) async fn observe(engine: Arc<MutationEngine>) -> Result<()> {
138|    let catalog = blob_catalog_dir_from_env();
139|    compatible_seal(&catalog)?;
140|    let mut observer = subscribe_incus_default_project().await?;
141|    readback_and_publish(&engine, &observer)
142|        .await
143|        .context("initial Incus snapshot publication failed")?;
144|    loop {
145|        observer.wait_for_lifecycle().await?;
146|        readback_and_publish(&engine, &observer)
147|            .await
148|            .context("Incus lifecycle readback publication failed")?;
149|    }
150|}
