152|/// Canonical Incus method integration. The native method, immediate readback,
153|/// seal validation, and full/private plus projected/public commit share the
154|/// observer lock. A completed provider mutation is never reported as success
155|/// if its readback or publication fails.
156|pub(crate) async fn dispatch_method(
157|    engine: &MutationEngine,
158|    method: &str,
159|    args: &serde_json::Value,
160|) -> Result<serde_json::Value> {
161|    let engine = engine.clone();
162|    let method = method.to_string();
163|    let args = args.clone();
164|    tokio::spawn(async move { dispatch_method_owned(&engine, &method, &args).await })
165|        .await
166|        .context("Incus operation owner failed; reconciliation may be required")?
167|}
168|
169|async fn dispatch_method_owned(
170|    engine: &MutationEngine,
171|    method: &str,
172|    args: &serde_json::Value,
173|) -> Result<serde_json::Value> {
174|    // Repair takes the session lifecycle lock before the host observation
175|    // lock. Keep that order here, and retain both guards through readback.
176|    let target = match method {
177|        "add_device" | "update_device" | "remove_device" => args.get("instance_name"),
178|        "create_instance" | "modify_instance" | "delete_instance" | "start_instance"
179|        | "stop_instance" | "restart_instance" | "freeze_instance" | "unfreeze_instance"
180|        | "snapshot_instance" | "exec_instance" => args.get("name"),
181|        _ => None,
182|    };
183|    let _identity_target = if let Some(target) = target {
184|        let target = target.as_str().context("Incus target name is invalid")?;
185|        if uuid::Uuid::parse_str(target).is_ok_and(|uuid| uuid.to_string() == target) {
186|            Some(crate::identity_sled_dispatch::guard_identity_incus_target(engine, target).await?)
187|        } else {
188|            None
189|        }
190|    } else {
191|        None
192|    };
193|    let _observation = engine.lock_host_observation().await;
194|    let _seeded_root = if let Some(target) = &_identity_target {
195|        target.verify_under_host_lock(method).await?
196|    } else {
197|        None
198|    };
199|    compatible_seal(&blob_catalog_dir_from_env())?;
200|    let observed = dispatch_incus_method_observed(method, args).await?;
201|    if let Some(snapshot) = observed.state {
202|        let prepared = prepare_observation(&blob_catalog_dir_from_env(), &snapshot).with_context(
203|            || {
204|                format!(
205|                    "Incus {method} completed but its state preparation failed; reconciliation is required"
206|                )
207|            },
208|        )?;
209|        engine
210|            .process_observed_state(
211|                PLUGIN,
212|                prepared.full_state,
213|                prepared.expected_schema_hash,
214|            )
215|            .await
216|            .map_err(anyhow::Error::msg)
217|            .with_context(|| {
218|                format!(
219|                    "Incus {method} completed but authoritative state publication failed; reconciliation is required"
220|                )
221|            })?;
222|    }
223|    Ok(observed.result)
224|}
