{"content":"1|//! Authenticated project effects, entered only through MutationEngine/D-Bus.
2|//! No ambient user, caller-supplied owner or cross-project store path is used.
3|use anyhow::{Context, Result, anyhow, bail};
4|use op_cozo_store::CozoGraphShuttle;
5|use op_plugins::state_plugins::{incus::IncusPlugin, project::*};
6|use serde_json::{Value, json};
7|use std::collections::{BTreeSet, HashMap};
8|use std::os::unix::fs::PermissionsExt;
9|use std::path::{Path, PathBuf};
10|use std::sync::{Arc, OnceLock};
11|use tokio::sync::Mutex;
12|
13|use crate::{interceptor::load_capability_grants, mutation_engine::MutationEngine};
14|
15|const PROJECT_ROOT: &str = "/var/lib/op-dbus/projects";
16|static PROJECT_LOCK: Mutex<()> = Mutex::const_new(());
17|type Stores = HashMap<String, Arc<CozoGraphShuttle>>;
18|static STORES: OnceLock<Mutex<Stores>> = OnceLock::new();
19|
20|fn canonical_id(id: &str) -> Result<()> {
21|    if uuid::Uuid::parse_str(id)?.to_string() != id {
22|        bail!("expected a canonical session/project UUID");
23|    }
24|    Ok(())
25|}
26|
27|fn project_path(id: &str) -> Result<PathBuf> {
28|    canonical_id(id)?;
29|    Ok(Path::new(PROJECT_ROOT).join(id))
30|}
31|
32|async fn catalog(engine: &MutationEngine, query: &'static str, params: Value) -> Result<Value> {
33|    let store = engine.identity_sled_store()?.cozo().clone();
34|    tokio::task::spawn_blocking(move || store.run_query(query, Some(params)))
35|        .await?
36|        .map_err(Into::into)
37|}
38|
39|fn decode_project_rows(value: Value) -> Result<Vec<Project>> {
40|    value
41|        .as_array()
42|        .ok_or_else(|| anyhow!("invalid project catalog rows"))?
43|        .iter()
44|        .map(|row| {
45|            serde_json::from_str(
46|                row["document"]
47|                    .as_str()
48|                    .ok_or_else(|| anyhow!("invalid project catalog document"))?,
49|            )
50|            .map_err(Into::into)
51|        })
52|        .collect()
53|}
54|
55|async fn list_projects(engine: &MutationEngine) -> Result<Vec<Project>> {
56|    decode_project_rows(
57|        catalog(
58|            engine,
59|            "?[document] := *project_catalog{document}",
60|            json!({}),
61|        )
62|        .await?,
63|    )
64|}
65|
66|async fn get_project(engine: &MutationEngine, id: &str) -> Result<Project> {
67|    canonical_id(id)?;
68|    decode_project_rows(
69|        catalog(
70|            engine,
71|            "?[document] := *project_catalog{project_id, document}, project_id = $id",
72|            json!({"id":id}),
73|        )
74|        .await?,
75|    )?
76|    .into_iter()
77|    .next()
78|    .ok_or_else(|| anyhow!("project access denied"))
79|}
80|
81|async fn save_project(engine: &MutationEngine, project: &Project) -> Result<()> {
82|    catalog(engine, "?[project_id, document] <- [[$id, $document]] :put project_catalog {project_id => document}",
83|        json!({"id":project.project_id, "document":serde_json::to_string(project)?})).await?;
84|    Ok(())
85|}
86|
87|async fn project_store(project: &Project, create: bool) -> Result<Arc<CozoGraphShuttle>> {
88|    let mut stores = STORES
89|        .get_or_init(|| Mutex::new(HashMap::new()))
90|        .lock()
91|        .await;
92|    if let Some(store) = stores.get(&project.project_id) {
93|        return Ok(store.clone());
94|    }
95|    let path = project_path(&project.project_id)?;
96|    if path.to_str() != Some(project.persistence_path.as_str()) {
97|        bail!("project persistence binding mismatch");
98|    }
99|    let store = tokio::task::spawn_blocking(move || -> Result<CozoGraphShuttle> {
100|        if create {
101|            std::fs::create_dir_all(&path)?;
102|        }
103|        // The project namespace is a UUID, never a user path. Refuse symlinks
104|        // at every owned level and retain private permissions on the host.
105|        for directory in [Path::new(PROJECT_ROOT).to_path_buf(), path.clone()] {
106|            let meta = std::fs::symlink_metadata(&directory)?;
107|            if !meta.is_dir() || meta.file_type().is_symlink() {
108|                bail!("unsafe project store directory");
109|            }
110|            std::fs::set_permissions(&directory, std::fs::Permissions::from_mode(0o700))?;
111|        }
112|        let db_path = path.join("cozo");
113|        if let Ok(meta) = std::fs::symlink_metadata(&db_path) {
114|            if meta.file_type().is_symlink() {
115|                bail!("unsafe project database path");
116|            }
117|        } else if !create {
118|            bail!("project database is missing; refusing to create an empty replacement");
119|        }
120|        Ok(CozoGraphShuttle::new_persistent(db_path)?)
121|    })
122|    .await??;
123|    let store = Arc::new(store);
124|    stores.insert(project.project_id.clone(), store.clone());
125|    Ok(store)
126|}
127|
128|async fn require_ready(project: &Project) -> Result<()> {
129|    if project.status != ProjectStatus::Ready {
130|        bail!("project provisioning is incomplete");
131|    }
132|    IncusPlugin::verify_project_container(
133|        &project.container_id,
134|        &project.owner_session_id,
135|        &project.persistence_path,
136|    )
137|    .await
138|}
139|
140|fn view_for(mut project: Project, session: &str) -> Project {
141|    if project.role_for(session) != Some(ProjectRole::Admin) {
142|        project.invitations.clear();
143|    }
144|    project
145|}
146|
147|pub(crate) async fn verified_session(
148|    engine: &MutationEngine,
149|    actor: &str,
150|    session: Option<&str>,
151|    genesis: Option<&str>,
152|) -> Result<String> {
153|    let session = session
154|        .filter(|id| !id.is_empty())
155|        .ok_or_else(|| anyhow!("verified session is required"))?;
156|    canonical_id(session)?;
157|    if let Some(external) = crate::external_mcp_session::verify_connected_session(
158|        engine, actor, session, genesis,
159|    ).await? {
160|        return Ok(external);
161|    }
162|    let sled = crate::identity_sled_dispatch::stored_session(engine, session)
163|        .await
164|        .context("identity credential projection is unavailable")?
165|        .ok_or_else(|| anyhow!("verified session does not exist"))?;
166|    if !sled.is_anchored()
167|        || sled.genesis.as_deref() != genesis
168|        || op_identity::session::derive_principal_id(&sled.wireguard_pubkey) != actor
169|        || sled
170|            .expires_at
171|            .is_some_and(|at| at != 0 && at <= chrono::Utc::now().timestamp())
172|    {
173|        bail!("verified session binding is invalid");
174|    }
175|    let principal =
176|        crate::human_principal_dispatch::resolve_key_for_assertion(&sled.wireguard_pubkey)
177|            .await
178|            .map_err(|_| anyhow!("principal registry is unavailable"))?
179|            .ok_or_else(|| anyhow!("session key is not registered"))?;
180|    if principal.revoked_at != 0 || principal.principal_id != actor {
181|        bail!("session principal is revoked or mismatched");
182|    }
183|    Ok(session.into())
184|}
185|
186|pub(crate) async fn dispatch(
187|    engine: &MutationEngine,
188|    method: &str,
189|    args: &Value,
190|    actor: &str,
191|    session: Option<&str>,
192|    genesis: Option<&str>,
193|) -> Result<Value> {
194|    let session = verified_session(engine, actor, session, genesis).await?;
195|    let grants: BTreeSet<String> = load_capability_grants(actor).into_iter().collect();
196|    let required = match method {
197|        "create" => "project.create",
198|        "invite" | "revoke_member" | "select_agent" => "project.admin",
199|        "put_document" => "project.write",
200|        "resolve_context" | "select_context" | "get_context" => "chat.context",
201|        "get" | "list" | "accept_invite" | "list_documents" => "project.read",
202|        _ => bail!("unknown project method"),
203|    };
204|    if !grants.contains(required) {
205|        bail!("exact project capability grant is required");
206|    }
207|    // Serializes ACL changes with all data access: a revocation cannot race a
208|    // stale read/modify/write of the project document. Cross-process entry is
209|    // exclusively the bridge; Cozo's process lock prevents a second writer.
210|    let _lock = PROJECT_LOCK.lock().await;
211|    if method == "resolve_context" {
212|        let input: ResolveContextInput = serde_json::from_value(args.clone())?;
213|        return Ok(serde_json::to_value(
214|            resolve_context(engine, &session, &grants, input).await?,
215|        )?);
216|    }
217|    if method == "select_context" {
218|        let input: SelectContextInput = serde_json::from_value(args.clone())?;
219|        let selection = ChatContextSelection {
220|            mode: input.mode,
221|            project_id: input.project_id,
222|            personal_namespace: input.personal_namespace,
223|        };
224|        // Validate exactly as a turn would resolve it before persisting.
225|        let resolved = resolve_selection(engine, &session, &grants, &selection).await?;
226|        let document = serde_json::to_string(&selection)?;
227|        catalog(
228|            engine,
229|            "?[session_id, document] <- [[$session, $document]] :put chat_context_selection {session_id => document}",
230|            json!({"session": session, "document": document}),
231|        )
232|        .await?;
233|        return Ok(serde_json::to_value(resolved)?);
234|    }
235|    if method == "get_context" {
236|        let _: GetContextInput = serde_json::from_value(args.clone())?;
237|        return Ok(serde_json::to_value(
238|            current_chat_context(engine, &session, &grants).await?,
239|        )?);
240|    }
241|    if method == "list" {
242|        let _: EmptyInput = serde_json::from_value(args.clone())?;
243|        return Ok(serde_json::to_value(ProjectListOutput {
244|            projects: list_projects(engine)
245|                .await?
246|                .into_iter()
247|                .filter(|p| p.role_for(&session).is_some())
248|                .map(|p| view_for(p, &session))
249|                .collect(),
250|        })?);
251|    }
252|    if method == "create" {
253|        let input: CreateProjectInput = serde_json::from_value(args.clone())?;
254|        if input.title.trim().is_empty() || input.title.len() > 256 {
255|            bail!("project title must contain 1–256 bytes");
256|        }
257|        if !input.capability_ceiling.is_subset(&grants) {
258|            bail!("project ceiling cannot exceed creator's exact grants");
259|        }
260|        if !input.allowed_agents.is_subset(&known_agent_ids()) {
261|            bail!("project agent is not in the declared catalog");
262|        }
263|        let fingerprint = std::env::var("OP_PROJECT_IMAGE_FINGERPRINT")
264|            .context("project image fingerprint is not configured")?;
265|        let pool = std::env::var("OP_PROJECT_STORAGE_POOL")
266|            .context("project storage pool is not configured")?;
267|        let id = uuid::Uuid::new_v4().to_string();
268|        let mut project = Project {
269|            project_id: id.clone(),
270|            title: input.title,
271|            owner_session_id: session.clone(),
272|            container_id: id.clone(),
273|            status: ProjectStatus::Provisioning,
274|            persistence_path: project_path(&id)?.to_string_lossy().into_owned(),
275|            members: vec![],
276|            invitations: vec![],
277|            capability_ceiling: input.capability_ceiling,
278|            allowed_agents: input.allowed_agents,
279|            selected_agent: None,
280|            created_at: chrono::Utc::now().timestamp(),
281|        };
282|        save_project(engine, &project).await?;
283|        project_store(&project, true).await?;
284|        IncusPlugin::create_project_container(
285|            &id,
286|            &session,
287|            &fingerprint,
288|            &pool,
289|            &project.persistence_path,
290|        )
291|        .await
292|        .with_context(|| format!("project {id} remains provisioning; inspect before retrying"))?;
293|        project.status = ProjectStatus::Ready;
294|        save_project(engine, &project).await?;
295|        return Ok(serde_json::to_value(ProjectOutput { project })?);
296|    }
297|    let id = args["project_id"]
298|        .as_str()
299|        .ok_or_else(|| anyhow!("project_id is required"))?;
300|    let mut project = get_project(engine, id).await?;
301|    if method == "accept_invite" {
302|        let input: AcceptInviteInput = serde_json::from_value(args.clone())?;
303|        project.accept_invitation(
304|            &session,
305|            &input.invitation_id,
306|            chrono::Utc::now().timestamp(),
307|        )?;
308|        save_project(engine, &project).await?;
309|    } else {
310|        project.authorize(
311|            &session,
312|            method == "put_document",
313|            matches!(method, "invite" | "revoke_member" | "select_agent"),
314|        )?;
315|        match method {
316|            "get" => {
317|                let _: ProjectInput = serde_json::from_value(args.clone())?;
318|            }
319|            "invite" => {
320|                let input: InviteInput = serde_json::from_value(args.clone())?;
321|                canonical_id(&input.invited_session_id)?;
322|                if !(1..=604800).contains(&input.ttl_seconds) {
323|                    bail!("invitation lifetime must be 1 second to 7 days");
324|                }
325|                if project.role_for(&input.invited_session_id).is_some() {
