186|    async fn incus_response_on_socket(
187|        socket: &std::path::Path,
188|        deadline: Duration,
189|        method: &str,
190|        path: &str,
191|        body: Option<&str>,
192|        etag: Option<&str>,
193|    ) -> Result<IncusHttpResponse> {
194|        const RESPONSE_LIMIT: usize = 16 * 1024 * 1024;
195|        if !(path == "/1.0"
196|            || path.starts_with("/1.0/")
197|            || path.starts_with("/1.0?")
198|            || matches!(
199|                path,
200|                "/internal/recover/validate" | "/internal/recover/import"
201|            ))
202|            || path.chars().any(|c| c.is_whitespace() || c.is_control())
203|            || path.contains(['#', '\\'])
204|            || path.split('?').next().is_some_and(|p| {
205|                p.split('/')
206|                    .any(|s| s == "." || s == ".." || s.contains('%'))
207|            })
208|        {
209|            anyhow::bail!("invalid local Incus API path");
210|        }
211|        let client = reqwest_unix::Client::builder()
212|            .unix_socket(socket.to_path_buf())
213|            .no_proxy()
214|            .redirect(reqwest_unix::redirect::Policy::none())
215|            .retry(reqwest_unix::retry::never())
216|            .connect_timeout(Duration::from_secs(3))
217|            .timeout(deadline)
218|            .build()
219|            .context("failed to build Incus UDS client")?;
220|        let mut request = client
221|            .request(method.parse()?, format!("http://localhost{path}"))
222|            .header("Accept", "application/json");
223|        if let Some(body) = body {
224|            request = request
225|                .header("Content-Type", "application/json")
226|                .body(body.to_owned());
227|        }
228|        if let Some(etag) = etag {
229|            request = request.header("If-Match", etag);
230|        }
231|        let mut response = request.send().await.context("Incus UDS request failed")?;
232|        let status = response.status();
233|        let etag = response
234|            .headers()
235|            .get("ETag")
236|            .map(|value| value.to_str().map(str::to_owned))
237|            .transpose()
238|            .context("invalid Incus ETag header")?;
239|        if response
240|            .content_length()
241|            .is_some_and(|length| length > RESPONSE_LIMIT as u64)
242|        {
243|            anyhow::bail!("Incus response exceeded size limit");
244|        }
245|        let mut bytes = Vec::new();
246|        while let Some(chunk) = response
247|            .chunk()
248|            .await
249|            .context("incomplete Incus response")?
250|        {
251|            if chunk.len() > RESPONSE_LIMIT.saturating_sub(bytes.len()) {
252|                anyhow::bail!("Incus response exceeded size limit");
253|            }
254|            bytes.extend_from_slice(&chunk);
255|        }
256|        if !status.is_success() {
257|            let error = serde_json::from_slice::<serde_json::Value>(&bytes)
258|                .ok()
259|                .and_then(|value| {
260|                    value
261|                        .get("error")
262|                        .and_then(|v| v.as_str())
263|                        .map(str::to_owned)
264|                })
265|                .unwrap_or_default();
266|            return Err(IncusHttpStatusError {
267|                status: status.as_u16(),
268|                detail: error,
269|            }
270|            .into());
271|        }
272|        Ok(IncusHttpResponse { body: bytes, etag })
273|    }
