276|    /// response. Incus answers most mutating calls (instance create/delete,
277|    /// etc.) with `"type": "async"` — a background operation, not the final
278|    /// result — whose completion must be awaited via `/1.0/operations/<id>/wait` before
279|    /// its outcome is known. Treating that initial "Operation created"
280|    /// response as the final answer (as this used to) misreads a real
281|    /// success as a blank error, since its own `error` field is `""`.
282|    async fn incus_api_call(method: &str, path: &str, body: Option<&str>) -> Result<Vec<u8>> {
283|        let value = IncusApi::local().call(method, path, body, None).await?;
284|        Ok(serde_json::to_vec(&value)?)
285|    }
