1419|    /// Call only after the host observation lock is held. The returned mount
1420|    /// guard must be kept through the native effect and its SHM readback.
1421|    pub(crate) async fn verify_under_host_lock(
1422|        &self,
1423|        method: &str,
1424|    ) -> anyhow::Result<Option<IdentityRootStartGuard>> {
1425|        let revision = load_revision(&self.store, &self.session_id).await?;
1426|        if let Some(sled) = revision_sled(&revision)?
1427|            && let Some(guard) = clean_provision::guard_start(&self.store, &revision, &sled).await?
1428|        {
1429|            anyhow::ensure!(method == "exec_instance", "clean identity storage and lifecycle are identity-owned");
1430|            return Ok(Some(guard.into()));
1431|        }
1432|        if let Some(sled) = revision_sled(&revision)?
1433|            && let Some(guard) = physical_root::guard_start(&self.store, &revision, &sled).await?
1434|        {
1435|            anyhow::ensure!(
1436|                matches!(method, "exec_instance" | "snapshot_instance"),
1437|                "physical identity provenance and lifecycle are identity-owned"
1438|            );
1439|            return Ok(Some(guard.into()));
1440|        }
1441|        let cozo = self.store.cozo.clone();
1442|        let session = self.session_id.clone();
1443|        let journal =
1444|            tokio::task::spawn_blocking(move || cozo.read_root_repair_journal(&session)).await??;
1445|        let cozo = self.store.cozo.clone();
1446|        let session = self.session_id.clone();
1447|        let provision =
1448|            tokio::task::spawn_blocking(move || cozo.read_seed_provision_journal(&session))
1449|                .await??;
1450|        if journal.is_none()
1451|            && let Some(provision) = provision
1452|        {
1453|            anyhow::ensure!(
1454|                provision.phase == "identity-committed",
1455|                "Incus target has incomplete seeded provision"
1456|            );
1457|            anyhow::ensure!(
1458|                matches!(method, "exec_instance" | "snapshot_instance"),
1459|                "seeded identity provenance and lifecycle are identity-owned"
1460|            );
1461|            let revision = load_revision(&self.store, &self.session_id).await?;
1462|            let sled = revision_sled(&revision)?.context("seeded identity disappeared")?;
1463|            return Ok(Some(
1464|                seed_provision::guard_start(&self.store, &revision, &sled)
1465|                    .await?
1466|                    .context("completed seed provision provenance disappeared")?
1467|                    .into(),
1468|            ));
1469|        }
1470|        match journal {
1471|            None => Ok(None),
1472|            Some(journal)
1473|                if journal.phase == "identity-committed"
1474|                    && matches!(method, "exec_instance" | "snapshot_instance") =>
1475|            {
1476|                let revision = load_revision(&self.store, &self.session_id).await?;
1477|                let sled = revision_sled(&revision)?
1478|                    .ok_or_else(|| anyhow::anyhow!("repaired identity disappeared"))?;
1479|                Ok(Some(
1480|                    root_repair::guard_own_root_start(&self.store, &revision, &sled)
1481|                        .await?
1482|                        .ok_or_else(|| anyhow::anyhow!("completed repair provenance disappeared"))?
1483|                        .into(),
1484|                ))
1485|            }
1486|            Some(_) => {
1487|                anyhow::bail!("Incus target is owned by identity root repair; use its owner route")
1488|            }
1489|        }
1490|    }
