2|use super::*;
3|
4|fn crc32(bytes: &[u8]) -> u32 {
5|    let mut value = !0u32;
6|    for byte in bytes {
7|        value ^= u32::from(*byte);
8|        for _ in 0..8 {
9|            value = (value >> 1) ^ (0xedb8_8320 & (0u32.wrapping_sub(value & 1)));
10|        }
11|    }
12|    !value
13|}
