738|    /// Apply a single Create action for an instance.
739|    pub async fn apply_create(instance: &IncusInstance) -> Result<Vec<String>> {
740|        let mut changes = Vec::new();
741|        let name = &instance.name;
742|
743|        // Determine the image to use; fall back to a sensible default
744|        let image = instance.image.as_deref().unwrap_or("images:debian/12");
745|
746|        let mut create_args = vec!["init".to_string(), image.to_string(), name.to_string()];
747|        if let Some(pool) = instance.storage_pool.as_deref() {
748|            create_args.push("--storage".to_string());
749|            create_args.push(pool.to_string());
750|        }
751|        if instance.profiles.is_empty() {
752|            create_args.push("--no-profiles".to_string());
753|        } else {
754|            for profile in Self::normalize_profiles(&instance.profiles) {
755|                create_args.push("--profile".to_string());
756|                create_args.push(profile);
757|            }
758|        }
759|        if instance.instance_type == "virtual-machine" {
760|            create_args.push("--vm".to_string());
761|        }
762|        let create_args_ref: Vec<&str> = create_args.iter().map(String::as_str).collect();
763|        log::info!("Creating instance '{}' from image '{}'", name, image);
764|        Self::run_incus_command(&create_args_ref)
765|            .await
766|            .with_context(|| format!("Failed to create instance '{}'", name))?;
767|        changes.push(format!("Created instance '{}'", name));
768|
769|        changes.extend(Self::sync_profiles(name, None, instance).await?);
770|        changes.extend(Self::sync_config(name, None, instance).await?);
771|        changes.extend(Self::sync_devices(name, None, instance).await?);
772|        changes.extend(Self::sync_status(name, None, instance).await?);
773|
774|        Ok(changes)
775|    }
